struct Point: Hashable {
    let x: Int, y: Int
    func hash(into h: inout Hasher) {
        h.combine(x); h.combine(y) }
}
print(Set([Point(x: 1, y: 2)]).count)

struct Bad: Hashable {
    let id: Int
    func hash(into h: inout Hasher) {}
}
let s: Set = [Bad(id: 1), Bad(id: 2)]
print(s.count) // still correct, just slower

